type NavItem = { label: string; icon: IconName; roles: Role[] }
type SelectOption = { value: string; label: string }

function ThemedSelect({ value, options, placeholder, ariaLabel, onChange }: { value: string; options: SelectOption[]; placeholder: string; ariaLabel: string; onChange: (value: string) => void }) {
  const [open, setOpen] = useState(false)
  const [activeIndex, setActiveIndex] = useState(0)
  const [query, setQuery] = useState('')
  const root = useRef<HTMLDivElement>(null)
  const selectedIndex = options.findIndex((option) => option.value === value)
  const selected = options[selectedIndex]
  const filteredOptions = filterSelectOptions(options, query)
  useEffect(() => {
    if (!open) return
    const closeOutside = (event: PointerEvent) => { if (!root.current?.contains(event.target as Node)) setOpen(false) }
    document.addEventListener('pointerdown', closeOutside)
    return () => document.removeEventListener('pointerdown', closeOutside)
  }, [open])
  const choose = (option: SelectOption | undefined) => { if (option) { onChange(option.value); setOpen(false); setQuery('') } }
  const onKeyDown = (event: React.KeyboardEvent<HTMLButtonElement | HTMLInputElement>) => {
    if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      event.preventDefault()
      if (!open) { setOpen(true); setActiveIndex(0) }
      else if (filteredOptions.length) setActiveIndex((index) => (index + (event.key === 'ArrowDown' ? 1 : -1) + filteredOptions.length) % filteredOptions.length)
    } else if (event.key === 'Enter') {
      if (event.currentTarget instanceof HTMLInputElement) { event.preventDefault(); choose(filteredOptions[activeIndex]) }
      else { event.preventDefault(); if (!open) { setOpen(true); setActiveIndex(0) } else choose(filteredOptions[activeIndex]) }
    } else if (event.key === ' ' && event.currentTarget instanceof HTMLButtonElement) {
      event.preventDefault()
      if (!open) { setOpen(true); setActiveIndex(0) } else choose(filteredOptions[activeIndex])
    } else if (event.key === 'Escape' && open) { event.preventDefault(); setOpen(false); setQuery('') }
    else if (event.key === 'Tab') setOpen(false)
  }
  return <div className={`themed-select${open ? ' is-open' : ''}`} ref={root}>
    <button type="button" className="themed-select-trigger" aria-label={ariaLabel} aria-haspopup="listbox" aria-expanded={open} onClick={() => { setOpen((current) => !current); setQuery(''); setActiveIndex(selectedIndex >= 0 ? selectedIndex : 0) }} onKeyDown={onKeyDown}>
      <span className={selected ? '' : 'is-placeholder'}>{selected?.label ?? placeholder}</span><Icon name="chevron" size={15} />
    </button>
    {open && <div className="themed-select-menu">
      <input className="themed-select-search" type="search" aria-label={`Cari ${ariaLabel.toLocaleLowerCase()}`} placeholder="Ketik untuk mencari…" value={query} onChange={(event) => { setQuery(event.target.value); setActiveIndex(0) }} onKeyDown={onKeyDown} autoComplete="off" />
      <div role="listbox" aria-label={ariaLabel}>{filteredOptions.length ? filteredOptions.map((option, index) => <button type="button" role="option" aria-selected={option.value === value} className={`themed-select-option${index === activeIndex ? ' is-active' : ''}`} key={option.value} onMouseEnter={() => setActiveIndex(index)} onClick={() => choose(option)}>{option.label}{option.value === value && <span aria-hidden="true">✓</span>}</button>) : <span className="themed-select-empty">Tidak ada hasil</span>}</div>
    </div>}
  </div>
}
