  const selectPage = (label: string) => { const page = pageRoutes.find((item) => item.label === label); if (page) navigate(page.path); setSidebarOpen(false) }; const loadData = async () => { setDataState('loading'); try { const [nextCustomers, nextProducts, nextOrders, nextInvoices, nextPayments] = await Promise.all([api.request<Customer[]>('/customers', { token }), api.request<Product[]>('/products', { token }), api.request<SalesOrderRecord[]>('/sales-orders', { token }), api.request<InvoiceRecord[]>('/invoices', { token }), api.request<PaymentRecord[]>('/payments', { token })]); setCustomerData(nextCustomers); setProductData(nextProducts); setSalesOrderData(nextOrders); setInvoiceData(nextInvoices); setPaymentData(nextPayments); const nextActivity = await api.request<Array<{ id: string; actor: string | null; action: ActivityAction; entity_type: string; entity_id: string; description: string; occurred_at: string }>>('/histories', { token }); setActivityData(nextActivity.map((entry) => ({ id: entry.id, time: new Date(entry.occurred_at).toLocaleString('id-ID'), actor: entry.actor ?? 'akun dihapus', actorName: entry.actor?.slice(0, 2).toUpperCase() ?? '—', action: entry.action, entity: `${entry.entity_type} · ${entry.entity_id}`, description: entry.description }))); setDataError(''); setDataState('ready') } catch (error) { setDataError(error instanceof Error ? error.message : 'Gagal memuat data'); setDataState('error') } }
